"use client";

import * as React from "react";
import { Check, ChevronRight, Copy } from "lucide-react";
import { cn } from "@/lib/utils";

export interface JsonViewerProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  data: unknown;
  /** tree depth (root = 0) to auto-expand; deeper nodes start collapsed. Default 1. */
  expandDepth?: number;
  /**
   * show the copy-to-clipboard button. Defaults to true.
   *
   * Replaces `hideCopy`, which was a negative boolean: `hideCopy={false}` read as a double negative, and the
   * prop's default behaviour could not be stated without inverting it in your head. Corrected while the
   * component is lifecycle-beta rather than carried to 1.0.
   */
  copyable?: boolean;
}

/**
 * JsonViewer — a collapsible, syntax-colored tree for arbitrary JSON data
 * (API responses, registry payloads, token diffs — a dev-tool surface the
 * site itself needs for `/docs/kinetixui-json` and friends). Distinct from
 * `TreeView`: this renders a *data structure* (object/array/primitive),
 * not a caller-composed hierarchy of `TreeItem`s, so expand state is
 * per-node uncontrolled rather than a lifted `expanded` prop — there's no
 * stable "value" to key a node by beyond its position in the data, and
 * nothing external needs to drive which nodes are open. Value colors reuse
 * the existing semantic tokens (`--success`/`--info`/`--warning`) rather
 * than introducing a separate syntax-highlighting palette. Gap-fill
 * addition (not in the original Figma source).
 */
const JsonViewer = React.forwardRef<HTMLDivElement, JsonViewerProps>(
  ({ data, expandDepth = 1, copyable = true, className, ...props }, ref) => {
    const [copied, setCopied] = React.useState(false);

    const copy = async () => {
      try {
        await navigator.clipboard.writeText(JSON.stringify(data, null, 2));
        setCopied(true);
        window.setTimeout(() => setCopied(false), 1500);
      } catch {
        // clipboard unavailable — no-op
      }
    };

    return (
      <div
        ref={ref}
        className={cn("relative overflow-auto rounded-md border bg-muted/30 p-3 font-mono text-xs", className)}
        {...props}
      >
        {copyable && (
          <button
            type="button"
            onClick={copy}
            aria-label="Copy JSON"
            className="absolute right-2 top-2 inline-flex size-6 items-center justify-center rounded-sm text-muted-foreground hover:bg-accent hover:text-foreground"
          >
            {copied ? <Check className="size-3.5" /> : <Copy className="size-3.5" />}
          </button>
        )}
        <div role="tree">
          <JsonNode value={data} depth={0} expandDepth={expandDepth} isLast />
        </div>
      </div>
    );
  },
);
JsonViewer.displayName = "JsonViewer";

function JsonNode({
  name,
  value,
  depth,
  expandDepth,
  isLast,
}: {
  name?: string;
  value: unknown;
  depth: number;
  expandDepth: number;
  isLast: boolean;
}) {
  const isContainer = value !== null && typeof value === "object";
  const [expanded, setExpanded] = React.useState(depth < expandDepth);

  if (!isContainer) {
    return (
      <div role="treeitem" style={{ paddingLeft: depth * 16 }}>
        {name !== undefined && <span className="text-muted-foreground">{JSON.stringify(name)}: </span>}
        <JsonPrimitive value={value} />
        {!isLast && <span className="text-muted-foreground">,</span>}
      </div>
    );
  }

  const isArray = Array.isArray(value);
  const entries: [string, unknown][] = isArray
    ? (value as unknown[]).map((v, i) => [String(i), v])
    : Object.entries(value as Record<string, unknown>);
  const openBracket = isArray ? "[" : "{";
  const closeBracket = isArray ? "]" : "}";

  if (entries.length === 0) {
    return (
      <div role="treeitem" style={{ paddingLeft: depth * 16 + 20 }}>
        {name !== undefined && <span className="text-muted-foreground">{JSON.stringify(name)}: </span>}
        <span>
          {openBracket}
          {closeBracket}
        </span>
        {!isLast && <span className="text-muted-foreground">,</span>}
      </div>
    );
  }

  return (
    <div role="treeitem" aria-expanded={expanded}>
      <div style={{ paddingLeft: depth * 16 }} className="flex items-start gap-1">
        <button
          type="button"
          onClick={() => setExpanded((e) => !e)}
          aria-label={expanded ? "Collapse" : "Expand"}
          className="mt-0.5 inline-flex size-4 shrink-0 items-center justify-center text-muted-foreground hover:text-foreground"
        >
          <ChevronRight className={cn("size-3 transition-transform", expanded ? "rotate-90" : "rtl:-scale-x-100")} />
        </button>
        <span>
          {name !== undefined && <span className="text-muted-foreground">{JSON.stringify(name)}: </span>}
          <span>{openBracket}</span>
          {!expanded && (
            <span className="text-muted-foreground">
              {" "}
              {entries.length} {isArray ? "item" : "key"}
              {entries.length === 1 ? "" : "s"}{" "}
            </span>
          )}
          {!expanded && <span>{closeBracket}</span>}
          {!expanded && !isLast && <span className="text-muted-foreground">,</span>}
        </span>
      </div>
      {expanded && (
        <>
          <div role="group">
            {entries.map(([key, val], i) => (
              <JsonNode
                key={key}
                name={isArray ? undefined : key}
                value={val}
                depth={depth + 1}
                expandDepth={expandDepth}
                isLast={i === entries.length - 1}
              />
            ))}
          </div>
          <div style={{ paddingLeft: depth * 16 }}>
            <span>{closeBracket}</span>
            {!isLast && <span className="text-muted-foreground">,</span>}
          </div>
        </>
      )}
    </div>
  );
}

function JsonPrimitive({ value }: { value: unknown }) {
  if (value === null) return <span className="italic text-muted-foreground">null</span>;
  if (value === undefined) return <span className="italic text-muted-foreground">undefined</span>;
  if (typeof value === "string") return <span className="text-success">{JSON.stringify(value)}</span>;
  if (typeof value === "number") return <span className="text-info">{value}</span>;
  if (typeof value === "boolean") return <span className="text-warning">{String(value)}</span>;
  return <span>{String(value)}</span>;
}

export { JsonViewer };

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Keeps the keyboard somewhere useful when a control removes the row it lives in.
 *
 * A remove button inside a chip or a list row destroys itself. Nothing then holds focus, so the
 * browser drops it on `<body>` and the next Tab starts again from the top of the document — a
 * keyboard user clearing three chips is sent back to the beginning after each one.
 *
 * Call this from the removing control's own handler, with the control and a selector that matches
 * one peer per removable row. The surviving peer is chosen BEFORE the removal, from document order:
 * the next row's control, or the previous one when the last row goes. It is focused once the
 * removal has actually happened AND left the keyboard stranded — so a handler
 * that removes nothing, or that moves focus somewhere of its own, keeps the focus it chose.
 *
 * @param trigger the control that was activated
 * @param peerSelector a selector matching the equivalent control on every row, e.g. "[data-kx-remove]"
 * @param options.scope where to look for peers; defaults to the trigger's parent list or its document
 * @param options.fallback where to go when no row survives — a chip group's own input, say
 *
 * Limit: the removal is expected to commit within a microtask or the next animation frame, which is
 * what a React state update from a click does. A removal awaited behind a network call lands later
 * than that, and its focus is the caller's to manage.
 */
export function focusAfterRemoval(
  trigger: HTMLElement | null | undefined,
  peerSelector: string,
  options: { scope?: HTMLElement | null; fallback?: HTMLElement | null } = {},
): void {
  if (!trigger?.isConnected) return;
  const scope = options.scope ?? trigger.closest("ul, ol, [data-kx-removable-group]") ?? trigger.ownerDocument.body;
  const peers = Array.from(scope.querySelectorAll<HTMLElement>(peerSelector));
  const here = peers.indexOf(trigger);
  const survivor = here < 0 ? null : (peers[here + 1] ?? peers[here - 1] ?? null);
  const target = survivor ?? options.fallback ?? null;
  if (!target) return;

  const settle = () => {
    // The trigger is still there: nothing was removed, so nothing should move.
    if (trigger.isConnected) return false;
    // And step in only where the removal actually stranded the keyboard. A handler that moved focus
    // somewhere of its own — the input a chip group is typed into, say — made a deliberate choice,
    // and that choice wins. Stranded means focus fell back to the document, which is what a browser
    // does when the focused element is taken out of the tree.
    const doc = trigger.ownerDocument;
    const active = doc.activeElement;
    const stranded = !active || active === doc.body || active === doc.documentElement || !active.isConnected;
    if (!stranded) return true;
    if (target.isConnected) target.focus();
    return true;
  };
  queueMicrotask(() => {
    if (settle()) return;
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(settle);
  });
}
